"""Second, independently structured implementation for differential testing."""
import zlib, struct

def recover(pages_hex, ckpt, log_hex):
    pages = [bytearray(bytes.fromhex(x)) for x in pages_hex]
    sizes = list(map(len, pages))
    data = bytes.fromhex(log_hex)
    tx = {}                     # id -> list of (page, off, count, payloadbytes)
    i = 0
    last = 0
    while True:
        if len(data) - i < 13:
            break
        plen = int.from_bytes(data[i:i+4], 'little')
        seq = int.from_bytes(data[i+4:i+8], 'little')
        kind = data[i+8]
        tid = int.from_bytes(data[i+9:i+13], 'little')
        if plen > 4096:
            break
        if len(data) - i < 13 + plen + 4:
            break
        chunk = data[i:i+13+plen]
        if int.from_bytes(data[i+13+plen:i+17+plen], 'little') != zlib.crc32(chunk) & 0xffffffff:
            break
        if not (0 < seq > last):
            break
        if tid <= 0:
            break
        body = chunk[13:]
        ok = True
        if kind == 1 or kind == 4:
            ok = (plen == 0)
        elif kind == 2:
            if plen < 6:
                ok = False
            else:
                pg = int.from_bytes(body[0:2], 'little')
                off = int.from_bytes(body[2:4], 'little')
                cnt = int.from_bytes(body[4:6], 'little')
                ok = (cnt > 0 and plen == 6 + cnt and pg < len(pages)
                      and 0 <= off and off + cnt <= sizes[pg])
        elif kind == 3:
            ok = (plen == 8)
        else:
            ok = False
        if not ok:
            break
        # semantics
        if kind == 1:
            tx[tid] = []
        elif kind == 2:
            if tid in tx:
                tx[tid].append(body)
        elif kind == 4:
            tx.pop(tid, None)
        else:
            got = tx.pop(tid, None)
            if got is not None:
                want_n = int.from_bytes(body[0:4], 'little')
                want_d = int.from_bytes(body[4:8], 'little')
                if want_n == len(got) and want_d == zlib.crc32(b''.join(got)) & 0xffffffff and seq > ckpt:
                    for pb in got:
                        pg = int.from_bytes(pb[0:2], 'little')
                        off = int.from_bytes(pb[2:4], 'little')
                        cnt = int.from_bytes(pb[4:6], 'little')
                        pages[pg][off:off+cnt] = pb[6:6+cnt]
        last = seq
        i += 17 + plen
    return [p.hex() for p in pages], i, last
